const need=(ok,message)=>{if(!ok)throw Error(message);};
export const cents=value=>{const n=Number(value);need(Number.isFinite(n)&&Math.abs(n)<=1e10,'Use a finite amount up to 10 billion.');return Math.round((n+Number.EPSILON)*100);};
export function rows(input,columns){const values=input.trim().split(/\n/).filter(s=>s.trim()).map(line=>line.split('|').map(s=>s.trim()));need(values.length>0&&values.length<=300,'Use 1–300 nonempty rows.');need(values.every(row=>row.length===columns),'Use exactly '+columns+' pipe-separated fields per row.');return values;}
export function budgetTotals(income,input){const list=rows(input,3).map(([name,planned,actual])=>{need(name&&Number(planned)>=0&&Number(actual)>=0,'Name every category and use nonnegative amounts.');return {name,planned:cents(planned),actual:cents(actual)};}),planned=list.reduce((s,r)=>s+r.planned,0),actual=list.reduce((s,r)=>s+r.actual,0),earnings=cents(income);return {list,planned,actual,income:earnings,plannedLeft:earnings-planned,actualLeft:earnings-actual};}
export function subscriptionTotals(input){const factors={weekly:52,fortnightly:26,monthly:12,quarterly:4,yearly:1};const list=rows(input,3).map(([name,price,cycle])=>{need(name&&+price>=0&&factors[cycle],'Use name | nonnegative price | weekly, fortnightly, monthly, quarterly or yearly.');return {name,price:cents(price),cycle,annual:cents(price)*factors[cycle]};});const annual=list.reduce((s,r)=>s+r.annual,0);return {list,annual,monthly:annual/12};}
export function debtPlan(input,extra=0,strategy='avalanche'){
 need(['avalanche','snowball'].includes(strategy),'Choose a payment priority.');const debts=rows(input,4).map(([name,balance,apr,minimum])=>{need(name&&+balance>0&&+apr>=0&&+apr<=100&&+minimum>0,'Use name | positive balance | APR 0–100 | positive monthly minimum.');return {name,balance:cents(balance),apr:+apr,minimum:cents(minimum)};});need(debts.length<=25&&+extra>=0,'Use up to 25 debts and nonnegative extra payments.');const original=debts.map(d=>({...d})),monthlyBudget=debts.reduce((s,d)=>s+d.minimum,0)+cents(extra),schedule=[];let totalInterest=0,totalPaid=0;
 for(let month=1;month<=1200;month++){
  const before=debts.reduce((s,d)=>s+d.balance,0);if(!before)return {months:month-1,totalInterest,totalPaid,monthlyBudget,schedule,original};let interest=0,paid=0,pool=monthlyBudget;
  for(const d of debts){if(!d.balance)continue;const i=Math.round(d.balance*d.apr/1200);d.balance+=i;interest+=i;const payment=Math.min(d.minimum,d.balance,pool);d.balance-=payment;pool-=payment;paid+=payment;}
  const priority=debts.filter(d=>d.balance>0).sort((a,b)=>strategy==='snowball'?a.balance-b.balance||b.apr-a.apr:b.apr-a.apr||a.balance-b.balance);
  for(const d of priority){const p=Math.min(pool,d.balance);d.balance-=p;pool-=p;paid+=p;if(!pool)break;}
  const remaining=debts.reduce((s,d)=>s+d.balance,0);need(remaining<before||remaining===0,'The payment budget does not reduce the modeled balance. Increase payments or review the inputs.');totalInterest+=interest;totalPaid+=paid;schedule.push({month,interest,paid,remaining,balances:debts.map(d=>d.balance)});
  if(!remaining)return {months:month,totalInterest,totalPaid,monthlyBudget,schedule,original};
 }throw Error('This plan exceeds 100 years. Increase the payment budget.');
}
export function unitPrice(price,quantity,unit,discount=0){const units={g:['mass',1],kg:['mass',1000],ml:['volume',1],l:['volume',1000],m:['length',1],cm:['length',.01],each:['count',1]};need(units[unit]&&Number.isFinite(+quantity)&&+price>=0&&+quantity>0&&+discount>=0&&+discount<=100,'Use a nonnegative price, positive quantity and discount from 0–100.');const [family,factor]=units[unit],net=cents(price)*(1-discount/100);return {family,baseQuantity:quantity*factor,perBase:net/(quantity*factor),net};}
export function cashFlow(opening,input){let current=cents(opening);const list=rows(input,3).map(([period,incoming,outgoing])=>{need(period&&+incoming>=0&&+outgoing>=0,'Use period | nonnegative receipts | nonnegative payments.');const start=current,receipts=cents(incoming),payments=cents(outgoing);current=start+receipts-payments;return {period,opening:start,receipts,payments,closing:current};});return {list,closing:current};}
export function inventory(input){return rows(input,5).map(([sku,name,quantity,cost,reorder])=>{need(sku&&name&&Number.isInteger(+quantity)&&+quantity>=0&&+cost>=0&&Number.isInteger(+reorder)&&+reorder>=0,'Use SKU | item | nonnegative whole quantity | cost | whole reorder level.');need(Number.isSafeInteger(+quantity*cents(cost)),'The stock value exceeds exact minor-unit arithmetic.');return {sku,name,quantity:+quantity,cost:cents(cost),reorder:+reorder,value:+quantity*cents(cost),low:+quantity<=+reorder};});}
export function parseIPv4(input){const parts=input.split('.');need(parts.length===4&&parts.every(p=>/^\d{1,3}$/.test(p)&&+p<=255),'Use a valid IPv4 address.');return parts.reduce((v,p)=>v*256+ +p,0);}
export const ipv4=value=>[24,16,8,0].map(shift=>Math.floor(value/2**shift)%256).join('.');
export function subnet(value){const match=value.trim().match(/^([^/]+)\/(\d{1,2})$/);need(match&&+match[2]<=32,'Use IPv4/CIDR, such as 192.0.2.143/27.');const address=parseIPv4(match[1]),prefix=+match[2],size=2**(32-prefix),network=Math.floor(address/size)*size,last=network+size-1,mask=2**32-size,usable=prefix===32?1:prefix===31?2:size-2;return {address:ipv4(address),prefix,size,network:ipv4(network),last:ipv4(last),mask:ipv4(mask),wildcard:ipv4(size-1),firstHost:ipv4(prefix>=31?network:network+1),lastHost:ipv4(prefix>=31?last:last-1),usable,interpretation:prefix===32?'Single host route':prefix===31?'Point-to-point /31 interpretation (RFC 3021)':'Conventional broadcast subnet',broadcast:prefix>=31?'Not assigned under this interpretation':ipv4(last)};}
export function permissionMode(bits,special=0,directory=false){need(bits.length===9&&bits.every(x=>typeof x==='boolean')&&Number.isInteger(special)&&special>=0&&special<=7,'Check permission bits.');const digits=[0,1,2].map(i=>(bits[i*3]?4:0)+(bits[i*3+1]?2:0)+(bits[i*3+2]?1:0));let symbolic=bits.map((set,i)=>set?'rwx'[i%3]:'-');if(special&4)symbolic[2]=bits[2]?'s':'S';if(special&2)symbolic[5]=bits[5]?'s':'S';if(special&1)symbolic[8]=bits[8]?'t':'T';return {octal:(special?String(special):'')+digits.join(''),symbolic:(directory?'d':'-')+symbolic.join('')};}
export function harSummary(raw){const data=typeof raw==='string'?JSON.parse(raw):raw;need(Array.isArray(data?.log?.entries)&&data.log.entries.length<=20000,'Use a HAR with up to 20,000 entries.');const entries=data.log.entries.map((entry,i)=>({i,method:String(entry.request?.method||''),url:String(entry.request?.url||''),status:Number(entry.response?.status||0),time:Math.max(0,Number(entry.time)||0),bytes:Math.max(0,Number(entry.response?.bodySize)||Number(entry.response?.content?.size)||0),type:String(entry.response?.content?.mimeType||'')}));return {data,entries,totalTime:entries.reduce((s,e)=>s+e.time,0),totalBytes:entries.reduce((s,e)=>s+e.bytes,0)};}
export function sanitizeHAR(data){const safe={log:{version:'1.2',creator:{name:'Nepocore reduced diagnostic export',version:'1'},entries:[]}};for(const entry of harSummary(data).entries){let url;try{const u=new URL(entry.url);u.username=u.password='';u.hash='';for(const key of [...u.searchParams.keys()])u.searchParams.set(key,'REDACTED');url=u.href;}catch{url='REDACTED_INVALID_URL';}safe.log.entries.push({startedDateTime:'1970-01-01T00:00:00.000Z',time:entry.time,request:{method:entry.method,url,httpVersion:'',headers:[],queryString:[],cookies:[],headersSize:-1,bodySize:-1},response:{status:entry.status,statusText:'',httpVersion:'',headers:[],cookies:[],content:{size:entry.bytes,mimeType:entry.type},redirectURL:'',headersSize:-1,bodySize:entry.bytes},cache:{},timings:{send:0,wait:entry.time,receive:0}});}return safe;}
const crcTable=Array.from({length:256},(_,i)=>{for(let j=0;j<8;j++)i=i&1?0xedb88320^(i>>>1):i>>>1;return i>>>0;});
export function zipStore(entries){need(entries.length>0&&entries.length<=500,'Use 1–500 ZIP entries.');const chunks=[],directory=[];let offset=0;for(const [name,raw]of entries){const data=raw instanceof Uint8Array?raw:new Uint8Array(raw),filename=new TextEncoder().encode(name);need(!name.includes('..')&&!name.startsWith('/')&&filename.length<256,'Use safe relative ZIP filenames.');let crc=0xffffffff;for(const b of data)crc=crcTable[(crc^b)&255]^(crc>>>8);crc=(crc^0xffffffff)>>>0;const h=new Uint8Array(30+filename.length),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,filename.length,true);h.set(filename,30);chunks.push(h,data);const c=new Uint8Array(46+filename.length),w=new DataView(c.buffer);w.setUint32(0,0x02014b50,true);w.setUint16(4,20,true);w.setUint16(6,20,true);w.setUint16(8,0x800,true);w.setUint32(16,crc,true);w.setUint32(20,data.length,true);w.setUint32(24,data.length,true);w.setUint16(28,filename.length,true);w.setUint32(42,offset,true);c.set(filename,46);directory.push(c);offset+=h.length+data.length;}const size=directory.reduce((s,c)=>s+c.length,0),end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,entries.length,true);v.setUint16(10,entries.length,true);v.setUint32(12,size,true);v.setUint32(16,offset,true);return new Blob([...chunks,...directory,end],{type:'application/zip'});}
